 84→func TestJSONLContent_MultipleObjects_AllRedacted(t *testing.T) {
 85→	t.Parallel()
 86→	// Regression test: JSONL with multiple top-level JSON objects must redact
 87→	// secrets in ALL objects, not just the first. The single-JSON fast path must
 88→	// not accidentally consume only the first object and return early.
 89→	input := `{"content":"safe text","id":"abc"}
 90→{"content":"key=` + highEntropySecret + `","id":"def"}
 91→{"content":"also safe","id":"ghi"}`
 92→
 93→	result, err := JSONLContent(input)
 94→	if err != nil {
 95→		t.Fatalf("unexpected error: %v", err)
 96→	}
 97→
 98→	// The secret in the second line should be redacted.
 99→	if strings.Contains(result, highEntropySecret) {
100→		t.Error("secret in second JSONL object was not redacted")
101→	}
102→	if !strings.Contains(result, "REDACTED") {
103→		t.Error("expected REDACTED in output")
104→	}
105→
106→	// IDs should be preserved (field-aware skip).
107→	for _, id := range []string{"abc", "def", "ghi"} {
108→		if !strings.Contains(result, id) {
109→			t.Errorf("ID %q should be preserved", id)
110→		}
111→	}
112→
113→	// Non-secret content should be preserved.
114→	if !strings.Contains(result, "safe text") {
115→		t.Error("safe text in first object was corrupted")
116→	}
117→	if !strings.Contains(result, "also safe") {
118→		t.Error("safe text in third object was corrupted")
119→	}
120→}
