 17→// secretPattern matches high-entropy strings that may be secrets.
 18→// Note: / is excluded to prevent matching entire file paths as single tokens.
 19→// Base64 and JWT tokens are still caught via high-entropy segments between slashes.
 20→var secretPattern = regexp.MustCompile(`[A-Za-z0-9+_=-]{10,}`)
 21→
 22→// entropyThreshold is the minimum Shannon entropy for a string to be considered
 23→// a secret. 4.5 was chosen through trial and error: high enough to avoid false
 24→// positives on common words and identifiers, low enough to catch typical API keys
 25→// and tokens which tend to have entropy well above 5.0.
 26→const entropyThreshold = 4.5
 27→
 28→// RedactedPlaceholder is the replacement text used for redacted secrets.
 29→const RedactedPlaceholder = "REDACTED"
 30→
 31→var (
 32→	gitleaksDetector     *detect.Detector
 33→	gitleaksDetectorOnce sync.Once
 34→)
 35→
 36→func getDetector() *detect.Detector {
 37→	gitleaksDetectorOnce.Do(func() {
 38→		d, err := detect.NewDetectorDefaultConfig()
 39→		if err != nil {
 40→			return
 41→		}
 42→		gitleaksDetector = d
 43→	})
 44→	return gitleaksDetector
 45→}
