 47→// region represents a byte range to redact.
 48→type region struct{ start, end int }
 49→
 50→// taggedRegion extends region with a label for typed replacement tokens.
 51→// Empty label = secret (produces "REDACTED"). Non-empty = PII (produces "[REDACTED_<LABEL>]").
 52→type taggedRegion struct {
 53→	region
 54→
 55→	label string
 56→}
 57→
 58→// String replaces secrets and PII in s using layered detection:
 59→// 1. Entropy-based: high-entropy alphanumeric sequences (threshold 4.5)
 60→// 2. Pattern-based: gitleaks regex rules (180+ known secret formats)
 61→// 3. PII detection: email, phone, address patterns (only when configured via ConfigurePII)
 62→// A string is redacted if ANY method flags it.
 63→func String(s string) string {
 64→	var regions []taggedRegion
 65→
 66→	// 1. Entropy-based detection (secrets — always on).
 67→	for _, loc := range secretPattern.FindAllStringIndex(s, -1) {
 68→		start, end := loc[0], loc[1]
 69→
 70→		// Don't consume characters that are part of JSON/string escape sequences.
 71→		// Example: in "controller.go\nmodel.go", the regex could match "nmodel"
 72→		// (consuming the 'n' from '\n'), and after replacement the '\' would be
 73→		// followed by 'R' from "REDACTED", creating invalid escape '\R'.
 74→		// Only skip for known JSON escape letters to avoid trimming real secrets
 75→		// that happen to follow a literal backslash in decoded content.
 76→		if start > 0 && s[start-1] == '\\' {
 77→			switch s[start] {
 78→			case 'n', 't', 'r', 'b', 'f', 'u', '"', '\\', '/':
 79→				start++
 80→				if end-start < 10 {
 81→					continue
 82→				}
 83→			}
 84→		}
 85→
 86→		if shannonEntropy(s[start:end]) > entropyThreshold {
 87→			regions = append(regions, taggedRegion{region: region{start, end}})
 88→		}
 89→	}
 90→
 91→	// 2. Pattern-based detection via gitleaks (secrets — always on).
 92→	if d := getDetector(); d != nil {
 93→		for _, f := range d.DetectString(s) {
 94→			if f.Secret == "" {
 95→				continue
 96→			}
 97→			searchFrom := 0
 98→			for {
 99→				idx := strings.Index(s[searchFrom:], f.Secret)
100→				if idx < 0 {
101→					break
102→				}
103→				absIdx := searchFrom + idx
104→				regions = append(regions, taggedRegion{region: region{absIdx, absIdx + len(f.Secret)}})
105→				searchFrom = absIdx + len(f.Secret)
106→			}
107→		}
108→	}
109→
110→	// 3. PII detection (opt-in — only runs when configured).
111→	regions = append(regions, detectPII(getPIIConfig(), s)...)
112→
113→	if len(regions) == 0 {
114→		return s
115→	}
116→
117→	// Merge overlapping regions and build result.
118→	sort.Slice(regions, func(i, j int) bool {
119→		if regions[i].start != regions[j].start {
120→			return regions[i].start < regions[j].start
121→		}
122→		if regions[i].end != regions[j].end {
123→			return regions[i].end > regions[j].end // larger region first
124→		}
125→		return regions[i].label < regions[j].label // deterministic tie-break
126→	})
127→	merged := []taggedRegion{regions[0]}
128→	for _, r := range regions[1:] {
129→		last := &merged[len(merged)-1]
130→		if r.start <= last.end {
131→			if r.end > last.end {
132→				last.end = r.end
133→			}
134→			// Keep the existing label (first/larger region wins)
135→		} else {
136→			merged = append(merged, r)
137→		}
138→	}
139→
140→	var b strings.Builder
141→	prev := 0
142→	for _, r := range merged {
143→		b.WriteString(s[prev:r.start])
144→		b.WriteString(replacementToken(r.label))
145→		prev = r.end
146→	}
147→	b.WriteString(s[prev:])
148→	return b.String()
149→}
