174→// JSONLContent parses each line as JSON to determine which string values
175→// need redaction, then performs targeted replacements on the raw JSON bytes.
176→// Lines with no secrets are returned unchanged, preserving original formatting.
177→//
178→// For multi-line JSON content (e.g., pretty-printed single JSON objects like
179→// OpenCode export), the function first attempts to parse the entire content as
180→// a single JSON value. This ensures field-aware redaction (which skips ID fields)
181→// is used instead of falling back to entropy-based detection on raw text lines,
182→// which would corrupt high-entropy identifiers.
183→func JSONLContent(content string) (string, error) {
184→	// Try parsing the entire content as a single JSON value first.
185→	// Uses a streaming decoder to avoid copying the full content into []byte.
186→	// After decoding, attempts a second Decode to confirm EOF — if it succeeds,
187→	// the content is JSONL (multiple values) and we fall through to line-by-line.
188→	trimmed := strings.TrimSpace(content)
189→	if len(trimmed) > 0 {
190→		dec := json.NewDecoder(strings.NewReader(trimmed))
191→		var parsed any
192→		if err := dec.Decode(&parsed); err == nil && isSingleJSONValue(dec) {
193→			// Content is a single JSON value (object/array) — redact field-aware.
194→			result, err := applyJSONReplacements(content, collectJSONLReplacements(parsed))
195→			if err != nil {
196→				return "", err
197→			}
198→			return result, nil
199→		}
200→	}
201→
202→	// Fall back to line-by-line JSONL processing.
203→	lines := strings.Split(content, "\n")
204→	var b strings.Builder
205→	for i, line := range lines {
206→		if i > 0 {
207→			b.WriteByte('\n')
208→		}
209→		lineTrimmed := strings.TrimSpace(line)
210→		if lineTrimmed == "" {
211→			b.WriteString(line)
212→			continue
213→		}
214→		var parsed any
215→		if err := json.Unmarshal([]byte(lineTrimmed), &parsed); err != nil {
216→			b.WriteString(String(line))
217→			continue
218→		}
219→		result, err := applyJSONReplacements(line, collectJSONLReplacements(parsed))
220→		if err != nil {
221→			return "", err
222→		}
223→		b.WriteString(result)
224→	}
225→	return b.String(), nil
226→}
