228→// applyJSONReplacements applies collected (original, redacted) string pairs
229→// to the raw JSON text, replacing JSON-encoded originals with their redacted forms.
230→// Returns s unchanged if repls is empty.
231→func applyJSONReplacements(s string, repls [][2]string) (string, error) {
232→	if len(repls) == 0 {
233→		return s, nil
234→	}
235→	for _, r := range repls {
236→		origJSON, err := jsonEncodeString(r[0])
237→		if err != nil {
238→			return "", err
239→		}
240→		replJSON, err := jsonEncodeString(r[1])
241→		if err != nil {
242→			return "", err
243→		}
244→		s = strings.ReplaceAll(s, origJSON, replJSON)
245→	}
246→	return s, nil
247→}
248→
249→// isSingleJSONValue returns true if the decoder has reached EOF (no more
250→// top-level values). This distinguishes a single JSON value (e.g., pretty-printed
251→// object) from JSONL (multiple concatenated values). We attempt a second Decode
252→// and require io.EOF rather than relying on dec.More(), which is documented for
253→// use inside arrays/objects and not for top-level value boundaries.
254→func isSingleJSONValue(dec *json.Decoder) bool {
255→	var discard json.RawMessage
256→	return dec.Decode(&discard) == io.EOF
257→}
