259→// collectJSONLReplacements walks a parsed JSON value and collects unique
260→// (original, redacted) string pairs for values that need redaction.
261→func collectJSONLReplacements(v any) [][2]string {
262→	seen := make(map[string]bool)
263→	var repls [][2]string
264→	var walk func(v any)
265→	walk = func(v any) {
266→		switch val := v.(type) {
267→		case map[string]any:
268→			if shouldSkipJSONLObject(val) {
269→				return
270→			}
271→			for k, child := range val {
272→				if shouldSkipJSONLField(k) {
273→					continue
274→				}
275→				walk(child)
276→			}
277→		case []any:
278→			for _, child := range val {
279→				walk(child)
280→			}
281→		case string:
282→			redacted := String(val)
283→			if redacted != val && !seen[val] {
284→				seen[val] = true
285→				repls = append(repls, [2]string{val, redacted})
286→			}
287→		}
288→	}
289→	walk(v)
290→	return repls
291→}
