293→// shouldSkipJSONLField returns true if a JSON key should be excluded from scanning/redaction.
294→// Skips "signature" (exact), ID fields (ending in "id"/"ids"), and common path/directory fields.
295→func shouldSkipJSONLField(key string) bool {
296→	if key == "signature" {
297→		return true
298→	}
299→	lower := strings.ToLower(key)
300→
301→	// Skip ID fields
302→	if strings.HasSuffix(lower, "id") || strings.HasSuffix(lower, "ids") {
303→		return true
304→	}
305→
306→	// Skip common path and directory fields from agent transcripts.
307→	// These appear frequently in tool calls and are structural, not secrets.
308→	switch lower {
309→	case "filepath", "file_path", "cwd", "root", "directory", "dir", "path":
310→		return true
311→	}
312→
313→	return false
314→}
315→
316→// shouldSkipJSONLObject returns true if the object has "type":"image" or "type":"image_url".
317→func shouldSkipJSONLObject(obj map[string]any) bool {
318→	t, ok := obj["type"].(string)
319→	return ok && (strings.HasPrefix(t, "image") || t == "base64")
320→}
