322→func shannonEntropy(s string) float64 {
323→	if len(s) == 0 {
324→		return 0
325→	}
326→	freq := make(map[byte]int)
327→	for i := range len(s) {
328→		freq[s[i]]++
329→	}
330→	length := float64(len(s))
331→	var entropy float64
332→	for _, count := range freq {
333→		p := float64(count) / length
334→		entropy -= p * math.Log2(p)
335→	}
336→	return entropy
337→}
338→
339→// jsonEncodeString returns the JSON encoding of s without HTML escaping.
340→func jsonEncodeString(s string) (string, error) {
341→	var buf bytes.Buffer
342→	enc := json.NewEncoder(&buf)
343→	enc.SetEscapeHTML(false)
344→	if err := enc.Encode(s); err != nil {
345→		return "", fmt.Errorf("json encode string: %w", err)
346→	}
347→	return strings.TrimSuffix(buf.String(), "\n"), nil
348→}
